model-everything/report  ok=undefined

// Generated by this plugin (Promela v1; booleans as 0/1 integers).
int pc = 0;
int retry = 0;
active proctype ModelEverything() {
  do
    :: (pc == 0) -> pc = 1;
    :: (pc == 1) -> pc = 2;
    :: (pc == 2) -> pc = 4;
    :: (pc == 1 && retry < 3) -> retry = retry + 1; pc = 3;
    :: (pc == 1 && retry >= 3) -> pc = 4;
    :: (pc == 3) -> pc = 1;
    :: (pc == 4) -> goto done;
  od
done: skip
}

